// HELIOS: STAR LAB
// Common: state layout, the stellar model, active regions, the magnetic field, camera, UI layout.
//
// Every visible property is derived from five inputs: temperature, radius, mass, rotation
// (as a fraction of breakup) and magnetic-cycle phase. Nothing is a per-star special case.

const float PI = 3.14159265, TAU = 6.28318531;
const float VERSION = 601.0;

// ---- Buffer A, row 0 -------------------------------------------------------------
const int S_CTRL  = 0;   // star, view (0 visible, 1 EUV), field overlay, paused
const int S_SLIDE = 1;   // slider targets 0..1: temperature, radius, rotation, cycle
const int S_EASED = 2;   // eased slider values (what is rendered)
const int S_CAM   = 3;   // eased camera: yaw, pitch, log2 zoom, ui hidden
const int S_CAMT  = 4;   // camera target: yaw, pitch, log2 zoom, modified
const int S_MOUSE = 5;   // last mouse: x, y, down, hit id
const int S_CLOCK = 6;   // star days, spin angle, granule phase, flare clock (s)
const int S_META  = 7;   // version, mass target, mass eased, time-lapse (days/s) eased
const int S_MODEL = 8;   // 8..15: packed Star
// Row 1: Planck table. Row 2: field sources (2 per region). Rows 3-5: active regions. Rows 8+: text table.
// Rows 6-7: interface text lines (see Buffer A), indexed by these:
const int TL_STAR = 0, TL_SLAB = 8, TL_SVAL = 12, TL_ZOOM = 16, TL_VIS = 17, TL_EUV = 18, TL_FIELD = 19, TL_PAUSE = 20;
const int TL_HIDE = 21, TL_SHOW = 22, NTL = 23;
const int NREG = 16;
const int NSTARS = 8;

// ---- Field-line geometry (Buffer B) ---------------------------------------------
const int NLINES = 256;            // 16 regions x 12 + 64 global
const int NODES = 64;
const int STRIDE = 73;             // 64 nodes, 8 chunk bounds, meta
const float RSS = 2.5;             // source surface: field is radial beyond it
const float RMAX = 3.4;
const int TILE = 32;               // Buffer C screen tiles

float sat(float x) { return clamp(x, 0.0, 1.0); }
float sq(float x) { return x * x; }
vec4 fetch(sampler2D s, int x, int y) { return texelFetch(s, ivec2(x, y), 0); }

uint pcg(uint v) { uint s = v * 747796405u + 2891336453u; uint w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u; return (w >> 22u) ^ w; }
float hashu(uint v) { return float(pcg(v) >> 8) * (1.0 / 16777216.0); }
vec4 hash4(uint a, uint b) {
    uint h = pcg(a * 1664525u + pcg(b));
    return vec4(hashu(h), hashu(h ^ 0x9e3779b9u), hashu(h ^ 0x85ebca6bu), hashu(h ^ 0xc2b2ae35u));
}
float hash13(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }
vec3 hash33(vec3 p) { p = fract(p * vec3(0.1031, 0.1030, 0.0973)); p += dot(p, p.yxz + 33.33); return fract((p.xxy + p.yxx) * p.zyx); }
float vnoise(vec3 p) {
    vec3 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
    return mix(mix(mix(hash13(i), hash13(i + vec3(1, 0, 0)), f.x), mix(hash13(i + vec3(0, 1, 0)), hash13(i + vec3(1, 1, 0)), f.x), f.y),
               mix(mix(hash13(i + vec3(0, 0, 1)), hash13(i + vec3(1, 0, 1)), f.x), mix(hash13(i + vec3(0, 1, 1)), hash13(i + vec3(1, 1, 1)), f.x), f.y), f.z);
}
// fBm that fades each octave to its mean once it is smaller than the pixel footprint fp.
float fbm(vec3 p, float fp, int octaves) {
    float s = 0.0, a = 0.5;
    for (int i = 0; i < octaves; i++) {
        s += a * mix(vnoise(p), 0.5, smoothstep(0.35, 1.0, fp));
        p = p * 2.03 + vec3(17.1, 9.7, 3.3); fp *= 2.03; a *= 0.5;
    }
    return s / (1.0 - a * 2.0 + 1e-4) ;
}
vec3 rotY(vec3 p, float a) { float c = cos(a), s = sin(a); return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }

// ---- Sliders and presets -------------------------------------------------------------
float sliderT(float x) { return 2400.0 * pow(45000.0 / 2400.0, x); }
float sliderR(float x) { return 0.008 * pow(1000.0 / 0.008, x); }
float sliderW(float x) { return 1e-4 * pow(0.95 / 1e-4, x); }       // omega = Omega / Omega_crit
float unT(float v) { return log(v / 2400.0) / log(45000.0 / 2400.0); }
float unR(float v) { return log(v / 0.008) / log(1000.0 / 0.008); }
float unW(float v) { return log(v / 1e-4) / log(0.95 / 1e-4); }

// Breakup period of a Roche star with polar radius R (Rsun) and mass M (Msun), days:
// Omega_crit^2 = 8 GM / (27 Rp^3).
float critPeriod(float R, float M) { return 0.2129 * sqrt(R * R * R / M); }

// T (K), polar R (Rsun), M (Msun), rotation period (days); cycle phase separately.
// Sun: IAU nominal. AB Dor A: Guirado+ 2011. Proxima: Boyajian+ 2012, P 83 d (Benedict+ 1998).
// Arcturus: Ramirez & Allende Prieto 2011. Betelgeuse: Joyce+ 2020, P 36 yr (Kervella+ 2018).
// Altair: Monnier+ 2007 (polar R, omega 0.923). Rigel: Przybilla+ 2006. Sirius B: Bond+ 2017.
vec4 presetStar(int k) {
    if (k == 1) return vec4(5080.0, 0.96, 0.86, 0.514);
    if (k == 2) return vec4(3042.0, 0.154, 0.122, 83.0);
    if (k == 3) return vec4(4286.0, 25.4, 1.08, 730.0);
    if (k == 4) return vec4(3600.0, 764.0, 16.5, 13150.0);
    if (k == 5) return vec4(7550.0, 1.63, 1.79, -0.923);         // negative: omega given directly
    if (k == 6) return vec4(12100.0, 78.9, 21.0, 150.0);
    if (k == 7) return vec4(25000.0, 0.0081, 1.02, 0.25);
    return vec4(5772.0, 1.0, 1.0, 25.4);
}
float presetCycle(int k) { return k == 0 ? 0.42 : (k == 2 ? 0.55 : 0.5); }
vec4 presetSliders(int k) {
    vec4 s = presetStar(k);
    float w = s.w < 0.0 ? -s.w : critPeriod(s.y, s.z) / s.w;
    return vec4(unT(s.x), unR(s.y), unW(w), presetCycle(k));
}

// ---- The stellar model -------------------------------------------------------------------
struct Star {
    float T, R, M, omega, cycle;
    float logg, logL, P, veq;
    float conv, alpha, Ro, giant;
    float gran, cgran, spotDT, beta;
    float eq, gdNorm, logY0, highLat;
    vec3 dipole; float flareRate;
    float wind, molsphere, wd, lapse;
    float chromo, coronaH, fullConv, cycleAmp;
};

// Effective gravity on the (ellipsoidal) Roche surface, units of GM/Rp^2. p on the surface.
float effGravity(vec3 p, float omega) {
    float r = length(p);
    vec3 g = -p / (r * r * r) + (8.0 / 27.0) * omega * omega * vec3(p.x, 0.0, p.z);
    return length(g);
}
// Equatorial / polar radius of a Roche surface rotating at omega.
float rocheEq(float w) {
    if (w < 0.05) return 1.0 + 4.0 * w * w / 27.0;
    return 3.0 / w * cos((PI + acos(w)) / 3.0);
}
// Photopic luminance (log) of a blackbody at temperature T, from the table in A, row 1.
vec4 planck(sampler2D A, float T) {
    float f = clamp(log(T / 1000.0) / log(100.0), 0.0, 1.0) * 255.0;
    int i = int(floor(f));
    return mix(fetch(A, i, 1), fetch(A, min(i + 1, 255), 1), fract(f));
}

Star makeStar(vec4 x, float M, float lapse) {
    Star s;
    s.T = sliderT(x.x); s.R = sliderR(x.y); s.M = M; s.omega = sliderW(x.z); s.cycle = x.w;
    s.logg = 4.438 + log(M / (s.R * s.R)) / log(10.0);
    s.eq = rocheEq(s.omega);
    s.logL = log(s.R * s.R * s.eq * pow(s.T / 5772.0, 4.0)) / log(10.0);
    s.P = critPeriod(s.R, M) / s.omega;
    s.veq = 2.0 * PI * s.R * s.eq * 695700.0 / (s.P * 86400.0);
    s.wd = smoothstep(5.5, 7.0, s.logg);
    // Convective envelope: granulation disappears in the late A stars.
    s.conv = (1.0 - smoothstep(6600.0, 7600.0, s.T)) * (1.0 - s.wd);
    // Rossby number with the convective turnover time of Wright+ 2011 (main sequence),
    // lengthened for inflated envelopes; X-ray activity saturates at Ro < 0.13.
    float Mc = clamp(M, 0.1, 1.36);
    float tauc = pow(10.0, 2.33 - 1.50 * Mc + 0.31 * Mc * Mc) * sqrt(max(s.R / pow(M, 0.8), 1.0));
    s.Ro = s.P / tauc;
    float logRx = -3.13 - 2.7 * max(log(s.Ro / 0.13) / log(10.0), 0.0);
    s.alpha = sat((logRx + 7.5) / 4.37) * s.conv;
    s.fullConv = smoothstep(0.42, 0.32, M) * s.conv;
    s.highLat = smoothstep(0.25, 0.04, s.Ro) * s.conv;
    s.cycleAmp = 1.0 - 0.75 * smoothstep(0.55, 1.0, s.alpha);
    // Granule size tracks the pressure scale height, d ~ T/g, scaled to 1 Mm on the Sun.
    s.gran = 0.00144 * (s.T / 5772.0) * (s.R / M);
    s.giant = smoothstep(1.2, -0.2, s.logg) * s.conv;          // a few huge cells (3D RHD supergiants)
    s.cgran = min(0.03 * pow(s.T / 5772.0, 1.5), 0.05) * s.conv;
    // Spot temperature deficit, approximate fit to Berdyugina 2005 (fig. 7).
    s.spotDT = clamp(0.62 * (s.T - 2800.0), 120.0, 2200.0);
    s.beta = mix(0.20, 0.08, s.conv);                          // gravity-darkening exponent
    // Normalise von Zeipel darkening so the area-averaged T^4 equals Teff^4.
    float tot = 0.0, area = 0.0;
    for (int j = 0; j < 24; j++) {
        float z = (float(j) + 0.5) / 24.0;
        vec3 n = vec3(sqrt(1.0 - z * z), z, 0.0), p = n * vec3(s.eq, 1.0, s.eq);
        float da = length(n / vec3(s.eq, 1.0, s.eq)) * s.eq * s.eq;
        tot += da * pow(effGravity(p, s.omega), 4.0 * s.beta); area += da;
    }
    s.gdNorm = pow(tot / area, -0.25);
    s.logY0 = 0.0;
    // Global dipole: polar field reverses through cycle maximum while its axis swings
    // through the equator. Fully convective dwarfs carry strong axisymmetric dipoles.
    float act = smoothstep(0.02, 0.5, s.alpha);
    float dip = 0.10 * act * (1.0 + 2.5 * s.fullConv + 1.5 * s.highLat);
    float ph = PI * s.cycle * s.cycleAmp;
    s.dipole = dip * vec3(0.45 * sin(ph), cos(ph), 0.0);
    s.flareRate = sat(0.9 * smoothstep(0.12, 0.75, s.alpha) + 0.5 * s.fullConv);
    float lumHot = smoothstep(3.8, 5.3, s.logL) * (1.0 - s.conv) * (1.0 - s.wd);
    s.wind = lumHot;
    s.molsphere = s.giant * smoothstep(3.0, 4.5, s.logL);
    s.lapse = lapse;
    s.chromo = s.giant;
    // Coronal pressure scale height ~ T_corona R / M (0.11 R at 1.5 MK on the Sun).
    s.coronaH = clamp(0.11 * (1.0 + 1.2 * s.alpha) * s.R / M, 0.05, 0.6);
    return s;
}

void packStar(Star s, int i, out vec4 o) {
    if (i == 0) o = vec4(s.T, s.R, s.M, s.omega);
    else if (i == 1) o = vec4(s.cycle, s.logg, s.logL, s.P);
    else if (i == 2) o = vec4(s.conv, s.alpha, s.Ro, s.giant);
    else if (i == 3) o = vec4(s.gran, s.cgran, s.spotDT, s.beta);
    else if (i == 4) o = vec4(s.eq, s.gdNorm, s.veq, s.highLat);
    else if (i == 5) o = vec4(s.dipole, s.flareRate);
    else if (i == 6) o = vec4(s.wind, s.molsphere, s.wd, s.lapse);
    else o = vec4(s.chromo, s.coronaH, s.fullConv, s.cycleAmp);
}
Star loadStar(sampler2D A) {
    vec4 a = fetch(A, 8, 0), b = fetch(A, 9, 0), c = fetch(A, 10, 0), d = fetch(A, 11, 0);
    vec4 e = fetch(A, 12, 0), f = fetch(A, 13, 0), g = fetch(A, 14, 0), h = fetch(A, 15, 0);
    Star s;
    s.T = a.x; s.R = a.y; s.M = a.z; s.omega = a.w;
    s.cycle = b.x; s.logg = b.y; s.logL = b.z; s.P = b.w;
    s.conv = c.x; s.alpha = c.y; s.Ro = c.z; s.giant = c.w;
    s.gran = d.x; s.cgran = d.y; s.spotDT = d.z; s.beta = d.w;
    s.eq = e.x; s.gdNorm = e.y; s.veq = e.z; s.highLat = e.w;
    s.dipole = f.xyz; s.flareRate = f.w;
    s.wind = g.x; s.molsphere = g.y; s.wd = g.z; s.lapse = g.w;
    s.chromo = h.x; s.coronaH = h.y; s.fullConv = h.z; s.cycleAmp = h.w;
    s.logY0 = 0.0;
    return s;
}
vec3 starAxes(Star s) { return vec3(s.eq, 1.0, s.eq); }

// ---- Active regions -------------------------------------------------------------------------
// A region is a tilted bipole: centre n, unit axis u pointing to the leading spot, half
// separation a, spot size w; strength e, flare level, leading polarity sign, age.
struct Region { vec3 n; float a; vec3 u; float w; float e; float flare; float lead; float age; };
Region loadRegion(sampler2D A, int k) {
    vec4 p = fetch(A, k, 3), q = fetch(A, k, 4), r = fetch(A, k, 5);
    Region g; g.n = p.xyz; g.a = p.w; g.u = q.xyz; g.w = q.w; g.e = r.x; g.flare = r.y; g.lead = r.z; g.age = r.w;
    return g;
}

// ---- Potential field with a source surface ------------------------------------------------
// Buried point sources, each with a grounded-sphere image so the field is radial at RSS.
// They are a boundary basis (every bipole carries zero net flux), not magnetic monopoles.
vec3 dipoleField(vec3 p, vec3 m) {
    float r2 = max(dot(p, p), 0.25), ir = inversesqrt(r2), ir3 = ir * ir * ir;
    return 3.0 * p * dot(m, p) * ir3 / r2 - m * ir3 + m / (RSS * RSS * RSS);
}
vec3 sourceField(vec3 p, vec4 src) {
    vec3 q = src.xyz; float ar = length(q);
    vec3 d = p - q, di = p - q * (RSS * RSS / dot(q, q));
    float d2 = max(dot(d, d), 1e-6), i2 = max(dot(di, di), 1e-6);
    return src.w * (d / (d2 * sqrt(d2)) - (RSS / ar) * di / (i2 * sqrt(i2)));
}

// ---- Camera ---------------------------------------------------------------------------------
const float CAMDIST = 12.0;
float uiScale(vec2 res) { return min(res.x / 960.0, res.y / 540.0); }
struct Cam { vec3 ro, fw, rt, up; float focal; vec2 center; };
Cam makeCam(vec4 c, vec2 res) {
    float zoom = exp2(c.z);
    vec3 d = vec3(sin(c.x) * cos(c.y), sin(c.y), cos(c.x) * cos(c.y));
    Cam k; k.ro = d * CAMDIST; k.fw = -d;
    k.rt = normalize(cross(k.fw, vec3(0, 1, 0))); k.up = cross(k.rt, k.fw);
    k.focal = 0.5 * res.y * CAMDIST / (1.75 / zoom);         // frame half-height 1.75 R at zoom 1
    k.center = vec2(0.5 * res.x, 0.5 * res.y + 34.0 * uiScale(res) * smoothstep(1.5, 0.0, c.z) * (1.0 - c.w));
    return k;
}
// Camera expressed in the rotating star frame.
Cam starCam(Cam k, float spin) { k.ro = rotY(k.ro, -spin); k.fw = rotY(k.fw, -spin); k.rt = rotY(k.rt, -spin); k.up = rotY(k.up, -spin); return k; }
vec3 camRay(Cam k, vec2 px) { return normalize(k.fw * k.focal + k.rt * (px.x - k.center.x) + k.up * (px.y - k.center.y)); }

// ---- UI layout (virtual 960 x 540 canvas, bottom-anchored, centred) -----------------------
vec2 uiPoint(vec2 px, vec2 res) { float s = uiScale(res); return vec2(px.x - 0.5 * (res.x - 960.0 * s), px.y) / s; }
// Star picker: x start of each name in the first row (14 px font, 7 px advance).
float starX(int k) { return k == 0 ? 20.0 : k == 1 ? 57.0 : k == 2 ? 115.0 : k == 3 ? 180.0 : k == 4 ? 252.0 : k == 5 ? 338.0 : k == 6 ? 396.0 : 447.0; }
float starW(int k) { return 7.0 * (k == 0 ? 3.0 : k == 1 ? 6.0 : k == 2 ? 7.0 : k == 3 ? 8.0 : k == 4 ? 10.0 : k == 5 ? 6.0 : k == 6 ? 5.0 : 8.0); }
vec2 sliderSpan(int k) { float x = 20.0 + float(k) * 235.0; return vec2(x, x + 210.0); }
const float ROW1 = 56.0, TRACK = 12.0;
// Hit ids: 0-3 sliders, 10-17 stars, 20 visible, 21 euv, 22 field, 23 pause, 24 zoom-, 25 zoom+, 26 hide, 27 show, -1 scene.
int uiHit(vec2 px, vec2 res, bool hidden) {
    vec2 p = uiPoint(px, res);
    if (hidden) return (p.x > 890.0 && p.x < 950.0 && p.y < 34.0) ? 27 : -1;
    if (p.y < 0.0 || p.y > 74.0 || p.x < 0.0 || p.x > 960.0) return -1;
    if (p.y < 40.0) {
        for (int k = 0; k < 4; k++) { vec2 s = sliderSpan(k); if (p.x > s.x - 8.0 && p.x < s.y + 8.0) return k; }
        return 99;
    }
    for (int k = 0; k < NSTARS; k++) if (p.x > starX(k) - 6.0 && p.x < starX(k) + starW(k) + 6.0) return 10 + k;
    if (p.x > 552.0 && p.x < 616.0) return 20;
    if (p.x > 617.0 && p.x < 654.0) return 21;
    if (p.x > 672.0 && p.x < 722.0) return 22;
    if (p.x > 737.0 && p.x < 788.0) return 23;
    if (p.x > 805.0 && p.x < 826.0) return 24;
    if (p.x > 864.0 && p.x < 886.0) return 25;
    if (p.x > 898.0 && p.x < 945.0) return 26;
    return 99;
}

// Buffer A: interface state, the derived stellar model, active regions, Planck table.
// iChannel0 = Buffer A (itself, nearest)
//
// Row 0: state (see Common). Row 1: blackbody colour table. Row 2: field sources.
// Rows 3-5: active regions. Regions are a deterministic function of the star's clock, so
// every pass sees the same spots, the same field and the same flares.

// CIE 1931 2-degree colour matching functions, 380-780 nm in 10 nm steps.
const vec3 CIE[41] = vec3[41](
    vec3(0.001368,3.9e-05,0.006450001),
    vec3(0.004243,0.00012,0.02005001),
    vec3(0.01431,0.000396,0.06785001),
    vec3(0.04351,0.00121,0.2074),
    vec3(0.13438,0.004,0.6456),
    vec3(0.2839,0.0116,1.3856),
    vec3(0.34828,0.023,1.74706),
    vec3(0.3362,0.038,1.77211),
    vec3(0.2908,0.06,1.6692),
    vec3(0.19536,0.09098,1.28764),
    vec3(0.09564,0.13902,0.8129501),
    vec3(0.03201,0.20802,0.46518),
    vec3(0.0049,0.323,0.272),
    vec3(0.0093,0.503,0.1582),
    vec3(0.06327,0.71,0.07824999),
    vec3(0.1655,0.862,0.04216),
    vec3(0.2904,0.954,0.0203),
    vec3(0.4334499,0.9949501,0.008749999),
    vec3(0.5945,0.995,0.0039),
    vec3(0.7621,0.952,0.0021),
    vec3(0.9163,0.87,0.001650001),
    vec3(1.0263,0.757,0.0011),
    vec3(1.0622,0.631,0.0008),
    vec3(1.0026,0.503,0.00034),
    vec3(0.8544499,0.381,0.00019),
    vec3(0.6424,0.265,4.999999e-05),
    vec3(0.4479,0.175,2e-05),
    vec3(0.2835,0.107,0.0),
    vec3(0.1649,0.061,0.0),
    vec3(0.0874,0.032,0.0),
    vec3(0.04677,0.017,0.0),
    vec3(0.0227,0.00821,0.0),
    vec3(0.01135916,0.004102,0.0),
    vec3(0.005790346,0.002091,0.0),
    vec3(0.002899327,0.001047,0.0),
    vec3(0.001439971,0.00052,0.0),
    vec3(0.0006900786,0.0002492,0.0),
    vec3(0.0003323011,0.00012,0.0),
    vec3(0.0001661505,6e-05,0.0),
    vec3(8.307527e-05,3e-05,0.0),
    vec3(4.150994e-05,1.499e-05,0.0)
);
// Linear sRGB per unit photopic luminance, and log luminance, of a blackbody.
vec4 planckEntry(int i) {
    float T = 1000.0 * pow(100.0, float(i) / 255.0);
    vec3 xyz = vec3(0);
    for (int j = 0; j < 41; j++) {
        float w = (380.0 + 10.0 * float(j)) * 1e-3, w5 = w * w * w * w * w;
        xyz += CIE[j] / (w5 * (exp(14387.77 / (w * T)) - 1.0));
    }
    vec3 rgb = mat3(3.24097, -0.96924, 0.05563, -1.53738, 1.87597, -0.20398, -0.49861, 0.04156, 1.05697) * xyz;
    return vec4(rgb / xyz.y, log(xyz.y));
}

float presetPeriod(int k) {
    vec4 s = presetStar(k);
    return s.w < 0.0 ? critPeriod(s.y, s.z) / -s.w : s.w;
}

// ---- Active regions ---------------------------------------------------------------------
// Each of the 16 slots lives through successive regions. Count follows the cycle, latitude
// follows the butterfly diagram (and moves poleward on fast rotators), tilt follows Joy's
// law, polarity order follows Hale's law, and differential rotation shears them.
Region makeRegion(Star s, int k, float days, float flareClock) {
    Region g;
    float h0 = hashu(uint(k) * 7919u + 17u), h1 = hashu(uint(k) * 104729u + 3u);
    float life = mix(14.0, 48.0, h1);
    float cyc = s.cycle, warp = pow(cyc, 0.75);
    float cycleShape = mix(1.0, 0.05 + 0.95 * sq(sin(PI * warp)), s.cycleAmp);
    float nfrac = smoothstep(0.03, 0.45, s.alpha) * cycleShape;
    float phase = days / life + h0, gen = floor(phase), age = fract(phase);
    vec4 r = hash4(uint(k), uint(int(gen) & 0xffffff)), q = hash4(uint(k) + 500u, uint(int(gen) & 0xffffff));
    float on = sat((nfrac - 0.92 * r.x) / 0.08);
    float hemi = r.z < 0.5 ? 1.0 : -1.0;
    float latDeg = mix(30.0, 8.0, cyc);
    latDeg = mix(latDeg, 62.0, s.highLat) + (r.y - 0.5) * mix(16.0, 12.0, s.highLat);
    float lat = hemi * radians(latDeg);
    float shear = 0.2 * smoothstep(0.02, 0.5, s.Ro) + 0.01;
    float lon = r.w * TAU - shear * TAU / s.P * sq(sin(lat)) * age * life;
    vec3 n = rotY(vec3(0.0, sin(lat), cos(lat)), lon);
    vec3 east = normalize(vec3(n.z, 0.0, -n.x)), north = normalize(vec3(0, 1, 0) - n * n.y);
    float gam = 0.5 * abs(lat);                                        // Joy's law
    g.n = n;
    g.u = cos(gam) * east - sin(gam) * hemi * north;                  // leading spot: ahead, equatorward
    float f = 0.35 + 1.3 * q.x * q.x * q.x;
    float big = 1.0 + 1.8 * smoothstep(0.45, 1.0, s.alpha);
    g.w = 0.024 * sqrt(f) * big;
    g.a = (0.03 + 0.035 * f) * sqrt(big) * (0.35 + 0.65 * smoothstep(0.0, 0.12, age)) * (1.0 + 0.8 * age);
    g.e = on * smoothstep(0.0, 0.1, age) * (1.0 - smoothstep(0.3, 1.0, age)) * f * s.conv;
    g.lead = hemi;                                                     // Hale's law for this cycle
    g.age = age;
    // Flares: real-time clock, so a flare is always watchable whatever the time-lapse.
    float I = 5.0, fp = flareClock / I + h1, slot = floor(fp);
    vec4 fr = hash4(uint(k) + 900u, uint(int(slot) & 0xffffff));
    float local = fract(fp) * I - fr.y * 2.5;
    float prof = local < 0.0 ? 0.0 : (1.0 - exp(-local / 0.10)) * exp(-local / 1.0);
    g.flare = fr.x < s.flareRate * sat(g.e) * 0.8 ? prof * (0.5 + fr.z) : 0.0;
    if (g.e < 0.002) { g.e = 0.0; g.flare = 0.0; }
    return g;
}


// ---- Interface text --------------------------------------------------------------------------
// Every string the interface shows is composed here once per frame: row 6 holds 5 texels of
// 12 chars per line (3 chars per channel), row 7 the lengths. Image only looks characters up.
const int TEXT_LEN = 166;
uint textWord(int i) { return (i < 21 ? (i < 10 ? (i < 5 ? (i < 2 ? (i < 1 ? 1097758035u : 1866735682u) : (i < 3 ? 1869762674u : (i < 4 ? 1634560376u : 1952674369u))) : (i < 7 ? (i < 6 ? 1937076853u : 1702126914u) : (i < 8 ? 1969579884u : (i < 9 ? 1816225139u : 1919508852u)))) : (i < 15 ? (i < 12 ? (i < 11 ? 1701275986u : 1919505260u) : (i < 13 ? 544437609u : (i < 14 ? 1768759362u : 543694958u))) : (i < 18 ? (i < 16 ? 1920540772u : (i < 17 ? 1886217556u : 1952543333u)) : (i < 19 ? 1382380149u : (i < 20 ? 1969841249u : 1953452659u))))) : (i < 31 ? (i < 26 ? (i < 23 ? (i < 22 ? 1869182049u : 1668891502u) : (i < 24 ? 1260414316u : (i < 25 ? 1970491936u : 1852796526u))) : (i < 28 ? (i < 27 ? 1852403045u : 1836412265u) : (i < 29 ? 1769171314u : (i < 30 ? 1634559854u : 1970104696u)))) : (i < 36 ? (i < 33 ? (i < 32 ? 1667589229u : 1768843628u) : (i < 34 ? 1767270254u : (i < 35 ? 1818388851u : 1448428901u))) : (i < 39 ? (i < 37 ? 1818585414u : (i < 38 ? 1634488420u : 1969311865u)) : (i < 40 ? 1766352243u : (i < 41 ? 1750295908u : 30575u)))))); }

// One string at a time is composed into a global scratch buffer (no array copies).
uint SW[16]; int SN;
void str() { for (int i = 0; i < 16; i++) SW[i] = 0u; SN = 0; }
// The table is decoded once, on the reset frame, into rows 8+ (one char per channel).
uint textChar(ivec2 t, int i) { int j = t.x + i, x = j >> 2; vec4 v = fetch(iChannel0, x % 256, 8 + x / 256); int c = j & 3; return uint(c == 0 ? v.x : c == 1 ? v.y : c == 2 ? v.z : v.w); }
void put(uint c) { if (SN < 60) { SW[SN >> 2] |= c << uint(8 * (SN & 3)); SN++; } }
void putT(ivec2 t) { for (int i = 0; i < t.y; i++) put(textChar(t, i)); }
void putInt(int v) {
    int d = 1;
    for (int k = 0; k < 8; k++) if (d * 10 <= v) d *= 10;
    for (int k = 0; k < 9; k++) { put(uint(48 + (v / d) % 10)); if (d == 1) break; d /= 10; }
}
void putFix(float v, int dec) {
    int m = dec == 0 ? 1 : dec == 1 ? 10 : dec == 2 ? 100 : dec == 3 ? 1000 : 10000;
    int n = int(floor(max(v, 0.0) * float(m) + 0.5)), ip = n / m;
    putInt(ip);
    if (dec > 0) {
        put(46u);
        int fr = n - ip * m, d = m / 10;
        for (int k = 0; k < 4; k++) { if (k >= dec) break; put(uint(48 + (fr / d) % 10)); d = max(d / 10, 1); }
    }
}
void putSig(float v) { putFix(v, v >= 100.0 ? 0 : v >= 10.0 ? 1 : v >= 1.0 ? 2 : v >= 0.1 ? 3 : 4); }


ivec2 starName(int k) {
    return k == 0 ? ivec2(0, 3) : k == 1 ? ivec2(3, 6) : k == 2 ? ivec2(9, 7) : k == 3 ? ivec2(16, 8)
         : k == 4 ? ivec2(24, 10) : k == 5 ? ivec2(34, 6) : k == 6 ? ivec2(40, 5) : ivec2(45, 8);
}


// Period or time in days, with sensible units.
void putTime(float d) {
    if (d < 1.0 / 24.0) { putSig(d * 1440.0); putT(ivec2(53, 4)); }
    else if (d < 1.0) { putSig(d * 24.0); putT(ivec2(57, 2)); }
    else if (d < 700.0) { putSig(d); putT(ivec2(59, 2)); }
    else { putSig(d / 365.25); putT(ivec2(61, 3)); }
}
void composeLine(int L, Star st) {
    vec4 ctrl = fetch(iChannel0, S_CTRL, 0), camT = fetch(iChannel0, S_CAMT, 0);
    str();
    if (L >= TL_STAR && L < TL_STAR + NSTARS) putT(starName(L - TL_STAR));
    else if (L >= TL_SLAB && L < TL_SLAB + 4) { int k = L - TL_SLAB; putT(k == 0 ? ivec2(64, 11) : k == 1 ? ivec2(75, 6) : k == 2 ? ivec2(81, 8) : ivec2(89, 5)); }
    else if (L >= TL_SVAL && L < TL_SVAL + 4) {
        int k = L - TL_SVAL;
        if (k == 0) { putInt(int(st.T + 0.5)); putT(ivec2(94, 2)); }
        else if (k == 1) { putSig(st.R); putT(ivec2(96, 5)); }
        else if (k == 2) putTime(st.P);
        else {
            float c = st.cycle;
            if (st.alpha < 0.02) putT(ivec2(101, 4));
            else putT(c < 0.15 || c > 0.88 ? ivec2(105, 7) : c < 0.32 ? ivec2(112, 6) : c < 0.58 ? ivec2(118, 7) : ivec2(125, 9));
        }
    }
    else if (L == TL_ZOOM) { put(120u); putInt(int(exp2(camT.z) + 0.5)); }
    else if (L == TL_VIS) putT(ivec2(134, 7));
    else if (L == TL_EUV) putT(ivec2(141, 3));
    else if (L == TL_FIELD) putT(ivec2(144, 5));
    else if (L == TL_PAUSE) putT(ctrl.w > 0.5 ? ivec2(149, 4) : ivec2(153, 5));
    else if (L == TL_HIDE) putT(ivec2(158, 4));
    else if (L == TL_SHOW) putT(ivec2(162, 4));
}

void mainImage(out vec4 O, in vec2 P) {
    ivec2 p = ivec2(P); vec2 res = iResolution.xy;
    vec4 meta = fetch(iChannel0, S_META, 0);
    bool reset = iFrame == 0 || meta.x != VERSION;
    O = vec4(0);
    if (p.y == 1) { if (p.x < 256) O = reset ? planckEntry(p.x) : fetch(iChannel0, p.x, 1); return; }
    if (p.y >= 2 && p.y <= 5) {
        if (reset) return;
        Star s = loadStar(iChannel0); vec4 clock = fetch(iChannel0, S_CLOCK, 0);
        int k = p.y == 2 ? p.x / 2 : p.x;
        if (k >= NREG) return;
        Region g = makeRegion(s, k, clock.x, clock.w);
        if (p.y == 2) {
            // Buried sources under the two spots; positive one first.
            vec3 lead = normalize(g.n + g.a * g.u), foll = normalize(g.n - g.a * g.u);
            vec3 pos = (g.lead > 0.0) == (p.x % 2 == 0) ? lead : foll;
            float depth = clamp(0.5 * g.w + 0.3 * g.a, 0.025, 0.1);
            float q = 0.02 * g.e * (1.0 + 1.5 * g.flare);
            O = q > 0.0 ? vec4(pos * (1.0 - depth), p.x % 2 == 0 ? q : -q) : vec4(0);
        }
        else if (p.y == 3) O = vec4(g.n, g.a);
        else if (p.y == 4) O = vec4(g.u, g.w);
        else O = vec4(g.e, g.flare, g.lead, g.age);
        return;
    }
    if (p.y >= 8 && p.y < 8 + (TEXT_LEN + 1023) / 1024) {
        int x = (p.y - 8) * 256 + p.x;
        if (p.x < 256 && 4 * x < TEXT_LEN) {
            if (!reset) { O = fetch(iChannel0, p.x, p.y); return; }
            uint w = textWord(x);
            O = vec4(w & 255u, (w >> 8) & 255u, (w >> 16) & 255u, w >> 24);
        }
        return;
    }
    if (p.y == 6 || p.y == 7) {
        if (reset || (p.y == 6 && p.x >= 5 * NTL) || (p.y == 7 && p.x >= NTL)) return;
        int L = p.y == 6 ? p.x / 5 : p.x;
        composeLine(L, loadStar(iChannel0));
        if (p.y == 7) { O = vec4(float(SN), 0, 0, 0); return; }
        int base = 12 * (p.x % 5);
        for (int c = 0; c < 4; c++) {
            uint v = 0u;
            for (int b = 0; b < 3; b++) { int i = base + 3 * c + b; v |= ((SW[i >> 2] >> uint(8 * (i & 3))) & 255u) << uint(8 * b); }
            O[c] = float(v);
        }
        return;
    }
    if (p.y != 0 || p.x > 15) return;

    // ---- state update (every row-0 texel runs it and keeps its own part) ----
    vec4 ctrl, slide, eased, cam, camT, mouse, clock;
    if (reset) {
        ctrl = vec4(0, 1, 0, 0); slide = presetSliders(0); eased = slide;
        cam = vec4(0.35, 0.16, 0, 0); camT = cam; mouse = vec4(0, 0, 0, -1); clock = vec4(0);
        meta = vec4(VERSION, 1.0, 1.0, presetPeriod(0) / 45.0);
    } else {
        ctrl = fetch(iChannel0, S_CTRL, 0); slide = fetch(iChannel0, S_SLIDE, 0); eased = fetch(iChannel0, S_EASED, 0);
        cam = fetch(iChannel0, S_CAM, 0); camT = fetch(iChannel0, S_CAMT, 0); mouse = fetch(iChannel0, S_MOUSE, 0);
        clock = fetch(iChannel0, S_CLOCK, 0);
    }
    float dt = clamp(iTimeDelta, 0.0, 0.1);
    bool down = iMouse.z > 0.0, fresh = down && mouse.z < 0.5;
    int hit = fresh ? uiHit(iMouse.xy, res, cam.w > 0.5) : (down ? int(mouse.w) : -2);
    if (fresh) {
        if (hit >= 10 && hit < 10 + NSTARS) {
            int k = hit - 10;
            slide = presetSliders(k); meta.y = presetStar(k).z; camT.w = 0.0; ctrl.x = float(k);
            camT.y = k == 5 ? 0.62 : 0.16;                    // Altair: show the hot pole
        }
        if (hit == 20) ctrl.y = 0.0;
        if (hit == 21) ctrl.y = 1.0;
        if (hit == 22) ctrl.z = 1.0 - ctrl.z;
        if (hit == 23) ctrl.w = 1.0 - ctrl.w;
        if (hit == 24) camT.z = max(camT.z - 1.0, 0.0);
        if (hit == 25) camT.z = min(camT.z + 1.0, 6.0);
        if (hit == 26) cam.w = 1.0;
        if (hit == 27) cam.w = 0.0;
    }
    if (down && hit >= 0 && hit < 4) {
        vec2 span = sliderSpan(hit);
        float v = sat((uiPoint(iMouse.xy, res).x - span.x) / (span.y - span.x));
        if (hit == 0) slide.x = v; else if (hit == 1) slide.y = v; else if (hit == 2) slide.z = v; else slide.w = v;
        camT.w = 1.0;
    }
    if (down && hit == -1 && mouse.z > 0.5) {
        vec2 d = (iMouse.xy - mouse.xy) * 3.2 / res.y / exp2(cam.z);
        camT.x -= d.x; camT.y = clamp(camT.y - d.y, -1.45, 1.45);
    }
    mouse = vec4(iMouse.xy, down ? 1.0 : 0.0, float(hit));

    float ke = 1.0 - exp(-dt * 9.0);
    eased = mix(eased, slide, ke);
    cam.xyz = mix(cam.xyz, camT.xyz, 1.0 - exp(-dt * 7.0));
    meta.z = exp(mix(log(meta.z), log(meta.y), ke));
    meta.w = exp(mix(log(meta.w), log(presetPeriod(int(ctrl.x)) / 45.0), ke));
    Star s = makeStar(eased, meta.z, meta.w);
    if (ctrl.w < 0.5 && !reset) {
        float lapse = meta.w;
        clock.x += dt * lapse;
        clock.y = mod(clock.y + dt * min(TAU * lapse / s.P, TAU / 3.0), TAU);
        float tauGran = 0.0058 * s.gran * s.R * 695.7;
        clock.z = mod(clock.z + dt * min(lapse / tauGran, 0.4), 1000.0);
        clock.w += dt;
    }
    if (p.x == S_CTRL) O = ctrl;
    else if (p.x == S_SLIDE) O = slide;
    else if (p.x == S_EASED) O = eased;
    else if (p.x == S_CAM) O = cam;
    else if (p.x == S_CAMT) O = camT;
    else if (p.x == S_MOUSE) O = mouse;
    else if (p.x == S_CLOCK) O = clock;
    else if (p.x == S_META) O = meta;
    else packStar(s, p.x - S_MODEL, O);
}

// Buffer B: field lines of the current potential field.
// iChannel0 = Buffer A (state, regions, sources)   iChannel1 = Buffer B (itself, nearest)
//
// 256 lines x 73 texels: 64 nodes (xyz in the star frame, w = arc length), 8 chunk bounding
// spheres, 1 meta texel. Node k is re-integrated every frame from the previous frame's node at
// the start of its 8-node chunk, so a line follows a changing field within 8 frames and costs
// at most 8 nodes of integration per texel. Bounds integrate their chunk from the same starts,
// so they always enclose this frame's nodes exactly.

vec4 SRC[2 * NREG];
int NSRC;
vec3 DIP;

vec3 field(vec3 p) {
    vec3 B = dipoleField(p, DIP);
    for (int i = 0; i < NSRC; i++) B += sourceField(p, SRC[i]);
    return B;
}

// Line seeds: 12 per region (8 around the positive spot, traced along B; 4 around the
// negative spot, traced against B), then 64 on a Fibonacci sphere traced outward.
vec4 seed(int i, out float energy, out float kind) {
    kind = 1.0;
    if (i < 12 * NREG) {
        int k = i / 12, j = i % 12;
        Region g = loadRegion(iChannel0, k);
        energy = g.e * (1.0 + 2.0 * g.flare); kind = g.age > 0.55 ? 1.0 : 0.0;
        bool pos = j < 8;
        vec3 lead = normalize(g.n + g.a * g.u), foll = normalize(g.n - g.a * g.u);
        vec3 c = (g.lead > 0.0) == pos ? lead : foll;
        vec3 e1 = normalize(cross(c, g.u)), e2 = cross(c, e1);
        float ang = float(j) * 2.39996, rad = g.w * (0.35 + 0.9 * fract(float(j) * 0.618));
        return vec4(normalize(c + rad * (cos(ang) * e1 + sin(ang) * e2)) * 1.002, pos ? 1.0 : -1.0);
    }
    float k = float(i - 12 * NREG), y = 1.0 - 2.0 * (k + 0.5) / 64.0, az = k * 2.39996;
    vec3 p = vec3(cos(az) * sqrt(1.0 - y * y), y, sin(az) * sqrt(1.0 - y * y)) * 1.002;
    vec3 B = field(p);
    float br = dot(B, normalize(p));
    energy = NSRC > 0 || dot(DIP, DIP) > 0.0 ? 0.35 * smoothstep(0.0, 0.05, abs(br)) : 0.0; kind = 1.0;
    return vec4(p, br >= 0.0 ? 1.0 : -1.0);
}

// Advance n nodes (two midpoint steps each). Lines stop where they re-enter the surface
// or leave the domain; beyond the source surface the field is radial.
vec4 advance(vec4 s, float dir, int n, inout vec3 lo, inout vec3 hi) {
    vec3 p = s.xyz; float arc = s.w;
    for (int i = 0; i < n; i++) {
        float r = length(p);
        if (r > RMAX || (r < 1.0001 && arc > 0.01)) break;
        for (int k = 0; k < 2; k++) {
            r = length(p);
            float ds = min(0.07, 0.006 + 0.045 * max(r - 1.0, 0.0));
            vec3 q;
            if (r >= RSS) q = p + normalize(p) * ds;
            else {
                vec3 v = normalize(field(p) + 1e-12) * dir;
                q = p + normalize(field(p + v * 0.5 * ds) + 1e-12) * dir * ds;
            }
            float rq = length(q);
            if (rq < 1.0 && arc > 0.004) {
                float f = clamp((r - 1.0) / max(r - rq, 1e-6), 0.0, 1.0);
                q = normalize(mix(p, q, f)); arc += f * ds; p = q; break;
            }
            arc += ds; p = q;
            if (rq > RMAX) break;
        }
        lo = min(lo, p); hi = max(hi, p);
    }
    return vec4(p, arc);
}

void mainImage(out vec4 O, in vec2 P) {
    int idx = int(P.y) * int(iResolution.x) + int(P.x);
    O = vec4(0);
    if (idx >= NLINES * STRIDE) return;
    int line = idx / STRIDE, slot = idx % STRIDE;
    NSRC = 0;
    for (int i = 0; i < 2 * NREG; i++) { vec4 s = fetch(iChannel0, i, 2); if (s.w != 0.0) { SRC[NSRC] = s; NSRC++; } }
    DIP = fetch(iChannel0, S_MODEL + 5, 0).xyz;
    float energy, kind;
    vec4 s0 = seed(line, energy, kind);
    float dir = s0.w; s0.w = 0.0;
    if (slot == STRIDE - 1) {
        // energy, direction, closed (last node back on the surface), kind
        // energy, direction, closed (last node back on the surface), cool.
        // Cool lines are low closed loops rooted in quiet or decayed flux: they hold the
        // dense chromospheric material of filaments and prominences.
        int w = int(iResolution.x);
        float peak = 1.0;
        for (int k = 0; k < NODES; k += 3) { int j = line * STRIDE + k; peak = max(peak, length(texelFetch(iChannel1, ivec2(j % w, j / w), 0).xyz)); }
        int j = line * STRIDE + NODES - 1;
        bool closed = length(texelFetch(iChannel1, ivec2(j % w, j / w), 0).xyz) < 1.02;
        O = vec4(energy < 0.02 ? 0.0 : energy, dir, closed ? 1.0 : 0.0, closed && kind > 0.5 && peak < 1.6 ? 1.0 : 0.0);
        return;
    }
    if (energy < 0.02) { O = slot < NODES ? s0 : vec4(0, 0, 0, -1); return; }
    vec3 lo = vec3(1e5), hi = vec3(-1e5);
    if (slot < NODES) {
        if (slot == 0) { O = s0; return; }
        int k0 = ((slot - 1) / 8) * 8;
        int j = line * STRIDE + k0, w = int(iResolution.x);
        vec4 st = k0 == 0 ? s0 : texelFetch(iChannel1, ivec2(j % w, j / w), 0);
        O = advance(st, dir, slot - k0, lo, hi);
        return;
    }
    // Chunk c spans nodes 8c .. 8c+8.
    int c = slot - NODES, w = int(iResolution.x);
    vec4 first = s0;
    if (c > 0) {
        int j = line * STRIDE + 8 * (c - 1);
        vec4 st = c == 1 ? s0 : texelFetch(iChannel1, ivec2(j % w, j / w), 0);
        first = advance(st, dir, 8, lo, hi);
    }
    lo = first.xyz; hi = first.xyz;
    int j = line * STRIDE + 8 * c;
    vec4 st = c == 0 ? s0 : texelFetch(iChannel1, ivec2(j % w, j / w), 0);
    advance(st, dir, c == 7 ? 7 : 8, lo, hi);
    O = vec4(0.5 * (lo + hi), 0.5 * length(hi - lo) + 0.004);
}

// Buffer C: which field lines can touch each 32 x 32 screen tile.
// iChannel0 = Buffer A (state)   iChannel1 = Buffer B (field lines)
//
// Four texels per tile, each a 64-line mask stored as four exact 16-bit integers. A line is
// listed when any of its eight chunk bounding spheres projects onto the tile.

vec4 lineTexel(int line, int slot) {
    int j = line * STRIDE + slot, w = int(iResolution.x);
    return texelFetch(iChannel1, ivec2(j % w, j / w), 0);
}

void mainImage(out vec4 O, in vec2 P) {
    O = vec4(0);
    vec2 res = iResolution.xy;
    int tx = (int(res.x) + TILE - 1) / TILE, ty = (int(res.y) + TILE - 1) / TILE;
    int idx = int(P.y) * int(res.x) + int(P.x), tile = idx / 4, group = idx % 4;
    if (tile >= tx * ty) return;
    vec4 ctrl = fetch(iChannel0, S_CTRL, 0);
    if (ctrl.y < 0.5 && ctrl.z < 0.5) return;            // no lines drawn in this view
    Star s = loadStar(iChannel0);
    vec3 ax = starAxes(s);
    float axm = max(ax.x, ax.y);
    Cam k = starCam(makeCam(fetch(iChannel0, S_CAM, 0), res), fetch(iChannel0, S_CLOCK, 0).y);
    vec2 lo = vec2(tile % tx, tile / tx) * float(TILE) - 4.0, hi = lo + float(TILE) + 8.0;
    uvec4 bits = uvec4(0);
    for (int l = 0; l < 64; l++) {
        int line = group * 64 + l;
        if (lineTexel(line, STRIDE - 1).x <= 0.0) continue;
        for (int c = 0; c < 8; c++) {
            vec4 b = lineTexel(line, NODES + c);
            if (b.w < 0.0) break;
            vec3 v = b.xyz * ax - k.ro;
            float z = dot(v, k.fw), r = b.w * axm;
            if (z + r <= 0.0) continue;
            bool hit = z <= r + 0.01;
            if (!hit) {
                vec2 c2 = k.center + k.focal * vec2(dot(v, k.rt), dot(v, k.up)) / z;
                float rp = k.focal * r / sqrt(max(z * z - r * r, 1e-6)) + 1.5;
                vec2 d = max(max(lo - c2, c2 - hi), vec2(0));
                hit = dot(d, d) < rp * rp;
            }
            if (hit) {
                uint bit = 1u << uint(l % 16);
                if (l < 16) bits.x |= bit; else if (l < 32) bits.y |= bit; else if (l < 48) bits.z |= bit; else bits.w |= bit;
                break;
            }
        }
    }
    O = vec4(bits);
}

// Buffer D: the star, its atmosphere and its field lines, linear HDR.
// iChannel0 = Buffer A (state, model, regions)   iChannel1 = Buffer B (lines)   iChannel2 = Buffer C (tiles)
//
// Visible light: every surface point has a local temperature (gravity darkening, granulation,
// spots, faculae) and emits a blackbody at the temperature found at optical depth tau = mu
// (grey Eddington atmosphere, T^4 = 3/4 Teff^4 (tau + 2/3)). Limb darkening and limb
// reddening follow from that alone, so they differ correctly between a red supergiant and a
// white dwarf. Disc centre is normalised to 1 for every star; colour is not.
// EUV: optically thin emission (chromospheric network, plage, flares, corona, loops, winds),
// displayed log-scaled in a He II 30.4 nm style false-colour palette.

Star S; vec4 CTRL, CLOCK; vec3 AX;
vec3 RN[NREG]; float RE[NREG];
vec4 SRC[2 * NREG]; int NSRC;
float FIL;                                // filament opacity along this pixel

// ---- Chromospheric material held by the field -------------------------------------------------
// The surface field gives two things the EUV disc needs. Its horizontal direction: chromospheric
// fibrils are dense material stretched along it (line-integral convolution of noise). And its
// polarity inversion lines: filaments are long dark ribbons of cool plasma suspended low above
// them, away from plage; past the limb the same material shows as prominences.
vec3 surfaceField(vec3 n) {
    vec3 p = n * 1.008, B = dipoleField(p, S.dipole);
    for (int i = 0; i < NSRC; i++) B += sourceField(p, SRC[i]);
    return B;
}
float filament(vec3 n, out vec3 t) {
    vec3 B = surfaceField(n);
    float br = dot(B, n), bm = length(B) + 1e-6;
    vec3 bt = B - br * n; t = bt / max(length(bt), 1e-6);
    float act = 0.0;
    for (int k = 0; k < NREG; k++) if (RE[k] > 0.0) act += RE[k] * exp(-(1.0 - dot(n, RN[k])) / 0.012);
    float wob = 0.6 + 0.8 * vnoise(n * 30.0);
    float q = sq(br / bm);
    float pil = exp(-q / (0.006 * wob)) + 0.25 * exp(-q / 0.05);    // ribbon plus its channel
    float seg = smoothstep(0.42, 0.62, vnoise(n * 4.5 + 11.3));        // only some stretches erupt into view
    return pil * seg * (1.0 - sat(3.0 * act)) * smoothstep(0.0, 0.02, length(S.dipole) + float(NSRC) * 0.01);
}
float streaks(vec3 n, vec3 t, float scale, float fp) {
    float a = 0.0;
    for (int k = -4; k <= 4; k++) a += vnoise((n + t * (float(k) * 1.1 / scale)) * scale);
    return mix(a / 9.0, 0.5, smoothstep(0.3, 1.0, fp * scale));
}

vec3 voronoi(vec3 p, float t) {
    vec3 c = floor(p), f = fract(p);
    float d1 = 8.0, d2 = 8.0, id = 0.0;
    for (int k = 0; k < 27; k++) {
        vec3 o = vec3(float(k % 3) - 1.0, float((k / 3) % 3) - 1.0, float(k / 9) - 1.0);
        vec3 h = hash33(c + o);
        vec3 d = o + 0.5 + 0.36 * sin(TAU * (h + t * (0.6 + 0.8 * h.zxy))) - f;
        float q = dot(d, d);
        if (q < d1) { d2 = d1; d1 = q; id = h.x; } else d2 = min(d2, q);
    }
    return vec3(sqrt(d1), sqrt(d2), id);
}
// Zero-mean convective pattern: bright granule bodies, dark intergranular lanes.
float convection(vec3 p, float t, float px, float lw) {
    float vis = 1.0 - smoothstep(0.25, 0.7, px);
    if (vis <= 0.0) return 0.0;
    vec3 v = voronoi(p, t);
    float body = 1.0 - smoothstep(0.0, 0.85, v.x);
    float lane = 1.0 - smoothstep(0.0, lw + 0.5 * px, v.y - v.x);
    return vis * (1.1 * (body - 0.4) - 1.1 * lane * (0.12 / (lw + 0.05)) * lw * 4.0 + 0.6 * (v.z - 0.5));
}

vec3 palette304(float x) {
    x = max(x, 0.0);
    vec3 c = mix(vec3(0), vec3(0.42, 0.03, 0.0), smoothstep(0.0, 0.25, x));
    c = mix(c, vec3(0.95, 0.30, 0.02), smoothstep(0.18, 0.55, x));
    c = mix(c, vec3(1.0, 0.70, 0.22), smoothstep(0.5, 0.85, x));
    return mix(c, vec3(1.0, 0.97, 0.82), smoothstep(0.8, 1.15, x)) * (1.0 + 0.6 * smoothstep(1.0, 1.6, x));
}

// ---- The surface ---------------------------------------------------------------------------
// Returns visible RGB (relative to disc centre) or EUV emission in .x when euv.
vec3 surface(vec3 s, float mu, float fp, bool euv) {
    vec3 p = s * AX;
    float T = S.T * S.gdNorm * pow(effGravity(p, S.omega), S.beta);
    // Granulation, and the few giant cells of supergiants.
    float F = 1.0 / S.gran;
    float gr = S.conv > 0.0 ? convection(s * F, CLOCK.z, fp * F, 0.07) : 0.0;
    float gc = 0.0;
    if (S.giant > 0.0) {
        vec3 wp = s * 2.4 + 0.8 * vec3(vnoise(s * 2.0 + 7.1), vnoise(s * 2.0 + 1.3), vnoise(s * 2.0 + 4.7)) - 0.4;
        // Supergiant surfaces (3D RHD, e.g. Chiavassa+ 2011) are soft bright plumes over dark
        // downflows, not a cell network: warped, sharpened fBm.
        float b1 = fbm(s * 2.6 + 1.6 * wp + CLOCK.z * 0.004, fp * 2.6, 4), b2 = fbm(s * 8.0 + 2.0 * wp, fp * 8.0, 3);
        gc = 2.6 * (smoothstep(0.30, 0.72, b1) - 0.5) + 0.8 * (b2 - 0.5);
    }
    float fine = fbm(s * 90.0, fp * 90.0, 3);
    T *= 1.0 + S.cgran * gr * (1.0 - 0.7 * S.giant) + 0.07 * S.giant * gc;
    float umbra = 0.0, pen = 0.0, plage = 0.0, flare = 0.0;
    for (int k = 0; k < NREG; k++) {
        if (RE[k] <= 0.0) continue;
        Region g = loadRegion(iChannel0, k);
        float reach = g.a + 4.0 * g.w + 0.04;
        if (dot(s, g.n) < 1.0 - 0.5 * reach * reach) continue;
        vec3 d = s - g.n;
        float x = dot(d, g.u), y = dot(d, cross(g.n, g.u));
        float sd = 1.0 - smoothstep(0.25, 0.75, g.age);
        float rl = g.w * sqrt(sd * sat(g.e * 1.5)) + 1e-4, rf = 0.75 * rl;
        float dl = length(vec2(x - g.a, y)) / rl + 0.25 * (fine - 0.5);
        float df = length(vec2(x + g.a, 1.25 * y)) / rf + 0.9 * (fine - 0.5) + 0.3 * (vnoise(s * 60.0) - 0.5);
        float um = max(1.0 - smoothstep(0.36, 0.46, dl), 1.0 - smoothstep(0.3, 0.42, df));
        float pn = max(1.0 - smoothstep(0.9, 1.05, dl), 1.0 - smoothstep(0.85, 1.0, df));
        // Radial penumbral filaments once they are resolved.
        float fil = 0.5 + 0.5 * sin(atan(y, x - g.a) * 70.0 + 6.0 * fine);
        fil = mix(0.5, fil, 1.0 - smoothstep(0.3, 1.0, fp * 70.0 / max(rl, 1e-3)));
        umbra = max(umbra, um); pen = max(pen, pn * (0.75 + 0.5 * fil));
        float ex = 1.2 * g.a + 2.6 * g.w, ey = 1.8 * g.w + 0.6 * g.a;
        plage += sqrt(RE[k]) * exp(-1.6 * (x * x / (ex * ex) + y * y / (ey * ey)));
        float rib = exp(-sq((abs(x) - 0.22 * g.a) / (0.07 * g.a + 0.003))) * exp(-sq(y / (1.3 * g.w + 0.004)));
        flare += g.flare * rib;
    }
    // Polar spots on fast rotators (Doppler imaging: AB Dor, LQ Hya...).
    float cap = S.highLat * smoothstep(0.80, 0.87, abs(s.y) + 0.06 * (fbm(s * 9.0, fp * 9.0, 3) - 0.5));
    umbra = max(umbra, cap * 0.8);
    float filigree = 0.55 + 0.9 * fine;
    if (!euv) {
        T -= S.spotDT * umbra + 0.35 * S.spotDT * max(pen - umbra, 0.0);
        T *= 1.0 + 0.05 * sat(plage) * filigree * (1.0 - mu) * (1.0 - umbra);   // faculae: bright at the limb
        float Te = T * pow(0.75 * (mu + 2.0 / 3.0), 0.25);
        vec4 pl = planck(iChannel0, Te), ref = planck(iChannel0, S.T * 1.0574), fl = planck(iChannel0, 9500.0);
        vec3 c = exp(pl.w - ref.w) * pl.rgb;
        return c + min(flare, 1.5) * 0.35 * exp(fl.w - ref.w) * fl.rgb;
    }
    // EUV disc: chromospheric network on the supergranulation scale, plage, flare ribbons,
    // coronal holes over the dipole poles, and the photosphere's own Wien tail.
    // Chromospheric mottling: domain-warped, so it swirls, with large dark filament channels.
    float drift = CLOCK.z * 0.004;
    vec3 wv = vec3(fbm(s * 6.0 + drift, fp * 6.0, 3), fbm(s * 6.0 + 5.2 - drift, fp * 6.0, 3), fbm(s * 6.0 + 9.1, fp * 6.0, 3)) - 0.5;
    float mott = fbm(s * 40.0 + 2.6 * wv, fp * 40.0, 4);
    float grain = fbm(s * 75.0 + 3.0 * wv, fp * 75.0, 3);
    float chan = smoothstep(0.50, 0.30, fbm(s * 4.0 + 3.0 * wv, fp * 4.0, 3));
    vec3 m = normalize(S.dipole + vec3(0, 1e-6, 0));
    float hole = smoothstep(0.62, 0.85, abs(dot(s, m))) * (0.35 + 0.65 * abs(cos(PI * S.cycle)));
    float E = S.conv * (0.06 + 0.75 * S.alpha) * (0.12 + 1.5 * sq(smoothstep(0.3, 0.8, mott)) + 0.9 * sq(sq(grain)) * 2.0)
            * (1.0 - 0.35 * chan * (1.0 - sat(plage))) * (1.0 - 0.7 * hole);
    if (S.alpha > 0.0) {
        vec3 t; float fil = filament(s, t);
        float fib = streaks(s, t, 70.0, fp), thr = streaks(s, t, 260.0, fp);
        // Dark fibrils everywhere the field lies flat, densest around plage; filaments on top.
        float horiz = 1.0 - abs(dot(normalize(surfaceField(s)), s));
        E *= 1.0 - 0.6 * smoothstep(0.5, 0.36, fib) * horiz * (0.25 + sat(2.0 * plage));
        float lumps = smoothstep(0.25, 0.7, vnoise(s * 55.0 + 3.0 * t));
        FIL = 0.8 * smoothstep(0.05, 1.0, fil) * mix(0.35, 1.0, lumps) * (0.6 + 0.6 * thr);
    }
    E += S.chromo * 0.5 * (0.6 + 0.8 * fbm(s * 4.0 + CLOCK.z * 0.01, fp * 4.0, 3));
    // Plage glows in fans of fine threads that follow the field out of each polarity.
    float fan = 1.0;
    if (plage > 0.02) { vec3 tf; filament(s, tf); fan = 0.35 + 1.5 * smoothstep(0.35, 0.75, streaks(s, tf, 330.0, fp)); }
    E += (2.4 * plage + 1.2 * sq(plage)) * filigree * fan * (1.0 - 0.6 * umbra) + 5.0 * flare;
    E *= 1.0 + 0.8 * sq(1.0 - mu);
    E += 2.0 * exp(-473289.0 * (1.0 / T - 1.0 / 25000.0)) + 0.035;
    return vec3(E, 0, 0);
}

// ---- Optically thin atmosphere --------------------------------------------------------------
// EUV: hydrostatic corona (scale height ~ T_c R / M) shaped by the helmet-streamer belt over the
// dipole's magnetic equator, coronal holes, active-region halos and radial rays; radiatively
// driven clumpy winds (beta-law, density ~ 1/(r^2 v)); extended supergiant chromospheres.
// Visible: the molecular layer of red supergiants (absorbs the disc edge, emits dim red).
vec2 atmosphere(vec3 ro, vec3 rd, float tEnd, bool euv) {
    float H = S.coronaH;
    float rout = 1.0 + max(max(euv ? max(6.0 * H * S.alpha, 0.03 * S.conv) : 0.0, (euv ? 2.6 : 0.0) * S.wind), max(euv ? 1.5 * S.chromo : 0.0, 0.7 * S.molsphere));
    if (rout <= 1.001) return vec2(0);
    float b = dot(ro, rd), c = dot(ro, ro) - rout * rout, h = b * b - c;
    if (h <= 0.0) return vec2(0);
    float t0 = max(-b - sqrt(h), 0.0), t1 = -b + sqrt(h);
    if (tEnd > 0.0) t1 = min(t1, tEnd);
    const int N = 40;
    float dt = (t1 - t0) / float(N), t = t0 + dt * hash13(vec3(gl_FragCoord.xy, CLOCK.w));
    vec3 m = normalize(S.dipole + vec3(0, 1e-6, 0));
    float E = 0.0, tau = 0.0;
    for (int i = 0; i < N; i++) {
        vec3 x = ro + rd * t; float r = length(x), hh = max(r - 1.0, 0.0); vec3 n = x / r;
        if (euv) {
            if (S.alpha > 0.0) {
                float dens = exp(-(1.0 / H) * (1.0 - 1.0 / r));
                float md = dot(n, m), belt = exp(-md * md / (0.10 / (1.0 + 1.5 * hh)));
                float ar = 0.0;
                for (int k = 0; k < NREG; k++) if (RE[k] > 0.0) ar += RE[k] * exp(-(1.0 - dot(n, RN[k])) / (0.004 + 0.03 * hh));
                float rays = vnoise(n * 38.0) * 0.7 + vnoise(n * 11.0) * 0.6;
                float hole = smoothstep(0.65, 0.9, abs(md)) * (0.35 + 0.65 * abs(cos(PI * S.cycle)));
                E += dens * dens * (0.3 + 1.6 * belt + 2.5 * ar) * (0.4 + rays) * (1.0 - 0.7 * hole) * (0.35 + 0.5 * S.alpha) * 1.3;
            }
            if (S.wind > 0.0) {
                float v = 0.02 + pow(max(1.0 - 0.98 / r, 0.0), 1.0), rho = min(1.0 / (r * r * v), 25.0);
                float cl = vnoise(vec3(n * 16.0) + vec3(0.0, 0.0, 5.0 * (r - CLOCK.w * 0.12)));
                E += S.wind * 0.05 * pow(rho, 1.5) * (0.2 + 3.0 * cl * cl * cl);
            }
            if (S.alpha > 0.0 && tEnd < 0.0 && hh < 0.09) {
                // Prominence: the filament seen edge-on, clumpy vertical threads.
                vec3 tt; float fil = filament(n, tt);
                if (fil > 0.01) {
                    float thr = vnoise(vec3(n * 240.0) + vec3(0.0, hh * 25.0, 0.0)) * vnoise(n * 70.0 + vec3(hh * 12.0));
                    E += 30.0 * smoothstep(0.1, 0.5, fil) * exp(-hh / 0.035) * smoothstep(0.0, 0.006, hh) * (0.15 + 2.0 * thr * thr);
                }
            }
            if (S.conv > 0.0 && hh < 0.03) {
                float sp = vnoise(vec3(n * 260.0)) * vnoise(vec3(n * 90.0) + 3.1);
                E += S.conv * (0.4 + S.alpha) * 14.0 * exp(-hh / (0.004 + 0.012 * sp)) * (0.3 + sp);
            }
            if (S.chromo > 0.0) E += S.chromo * 0.55 * exp(-hh / 0.45) * (0.5 + vnoise(x * 3.0 + CLOCK.z * 0.01));
        } else {
            float rho = S.molsphere * exp(-hh / 0.16) * (0.5 + vnoise(x * 4.0 + CLOCK.z * 0.01));
            tau += 2.6 * rho * dt;
            E += 0.10 * rho * dt * exp(-tau);
        }
        t += dt;
    }
    return vec2(E * (euv ? dt : 1.0), tau);
}

// ---- Field lines ---------------------------------------------------------------------------------
vec2 erfa(vec2 x) { vec2 sg = sign(x); x = abs(x); vec2 t = 1.0 / (1.0 + 0.3275911 * x);
    return sg * (1.0 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * exp(-x * x)); }
vec4 node(int line, int slot) {
    int j = line * STRIDE + slot, w = int(iResolution.x);
    return texelFetch(iChannel1, ivec2(j % w, j / w), 0);
}
// Overlay: thin lines (closed loops warm, open field by polarity). EUV: emitting loops.
// EUV: loops rooted in plage glow as clumpy condensations, not uniform strings. Low loops over
// quiet or decayed flux are skipped: their cool material is drawn from the surface field instead.
void fieldLines(vec3 ro, vec3 rd, float tEnd, float fp, vec2 px, bool euv, bool overlay, out vec4 ov, out float uv, out vec2 cool) {
    ov = vec4(0); uv = 0.0; cool = vec2(0);
    vec2 res = iResolution.xy;
    int tx = (int(res.x) + TILE - 1) / TILE, tile = int(px.x) / TILE + (int(px.y) / TILE) * tx;
    float lim = tEnd > 0.0 ? tEnd : 1e5;
    for (int g = 0; g < 4; g++) {
        int j = tile * 4 + g, w = int(res.x);
        uvec4 mask = uvec4(texelFetch(iChannel2, ivec2(j % w, j / w), 0));
        for (int ch = 0; ch < 4; ch++) {
            uint bits = ch == 0 ? mask.x : ch == 1 ? mask.y : ch == 2 ? mask.z : mask.w;
            while (bits != 0u) {
                int bit = int(log2(float(bits & (~bits + 1u))) + 0.5); bits &= bits - 1u;
                int line = g * 64 + ch * 16 + bit;
                vec4 meta = node(line, STRIDE - 1);
                bool closed = meta.z > 0.5, cold = meta.w > 0.5;
                vec3 tint = closed ? vec3(1.0, 0.80, 0.52) : (meta.y > 0.0 ? vec3(1.0, 0.32, 0.62) : vec3(0.30, 0.68, 1.0));
                float ebase = meta.x * (closed ? 1.0 : 0.30), eeuv = sqrt(meta.x) * (closed ? 2.2 : 0.04);
                for (int c = 0; c < 8; c++) {
                    vec4 bd = node(line, NODES + c);
                    if (bd.w < 0.0) break;
                    vec3 v = bd.xyz - ro; float tc = dot(v, rd);
                    float pad = bd.w + 0.02 + 3.0 * tc * fp;
                    if (dot(v, v) - tc * tc > pad * pad || tc + bd.w < 0.0 || tc - bd.w > lim) continue;
                    vec4 a = node(line, 8 * c);
                    int last = c == 7 ? 7 : 8;
                    for (int q = 1; q <= last; q++) {
                        vec4 b = node(line, 8 * c + q);
                        vec3 ab = b.xyz - a.xyz;
                        float ta = dot(a.xyz - ro, rd), tb = dot(b.xyz - ro, rd);
                        vec3 pa = a.xyz - ro - rd * ta, v = ab - rd * (tb - ta);
                        float vv = dot(v, v);
                        if (vv > 1e-12 && max(ta, tb) > 0.0) {
                            // Gaussian tube integrated along the projected segment: joints add up exactly.
                            float u = -dot(pa, v) / vv, d2 = max(dot(pa, pa) - u * u * vv, 0.0);
                            float uc = clamp(u, 0.0, 1.0), t = mix(ta, tb, uc);
                            float r = length(a.xyz + ab * uc), hh = r - 1.0, arc = mix(a.w, b.w, uc);
                            float spx = 0.6 * t * fp;
                            if (t < lim) {
                                if (overlay) {
                                    float so = max(spx, 0.0006), kk = sqrt(vv) / (1.4142 * so);
                                    vec2 er = erfa(vec2(1.0 - u, -u) * kk);
                                    float cov = exp(-0.5 * d2 / (so * so)) * 0.5 * (er.x - er.y)
                                              * smoothstep(3.3, 2.0, r) * min(1.0, 0.3 + 2.0 * meta.x);
                                    ov.rgb += tint * cov; ov.a += cov;
                                }
                                if (euv) {
                                    vec3 cp = mix(a.xyz, b.xyz, uc);
                                    float sw = cold ? 0.006 + 0.004 * hh : (0.009 + 0.02 * hh) * (closed ? 1.0 : 2.5);
                                    float sg = sqrt(sw * sw + spx * spx), kk = sqrt(vv) / (1.4142 * sg);
                                    vec2 er = erfa(vec2(1.0 - u, -u) * kk);
                                    float prof = exp(-0.5 * d2 / (sg * sg)) * 0.5 * (er.x - er.y) * (sw / sg);
                                    vec3 fl = cp * 28.0 + float(line) * 1.7 + vec3(0.0, 0.0, CLOCK.w * 0.25);
                                    float blob = (0.3 + 0.7 * smoothstep(0.2, 0.8, vnoise(fl))) * (0.5 + 0.8 * vnoise(cp * 110.0 - CLOCK.w * 0.3));
                                    blob = mix(blob, 0.75, smoothstep(0.08, 0.35, hh));
                                    if (!cold) {
                                        // Diffuse clumpy plasma plus a faint fibril core.
                                        float sc = sqrt(0.0016 * 0.0016 + spx * spx), kc = sqrt(vv) / (1.4142 * sc);
                                        vec2 ec = erfa(vec2(1.0 - u, -u) * kc);
                                        float core = exp(-0.5 * d2 / (sc * sc)) * 0.5 * (ec.x - ec.y) * (0.0016 / sc);
                                        uv += eeuv * (prof * blob * blob * 1.5 + core * blob * 0.5) * (exp(-hh / 0.12) + 0.3 * exp(-hh / 0.5));
                                    }
                                }
                            }
                        }
                        a = b;
                    }
                }
            }
        }
    }
}

void mainImage(out vec4 O, in vec2 P) {
    vec2 res = iResolution.xy;
    S = loadStar(iChannel0); CTRL = fetch(iChannel0, S_CTRL, 0); CLOCK = fetch(iChannel0, S_CLOCK, 0); AX = starAxes(S);
    for (int k = 0; k < NREG; k++) { RN[k] = fetch(iChannel0, k, 3).xyz; RE[k] = fetch(iChannel0, k, 5).x; }
    NSRC = 0;
    for (int i = 0; i < 2 * NREG; i++) { vec4 q = fetch(iChannel0, i, 2); if (q.w != 0.0) { SRC[NSRC] = q; NSRC++; } }
    bool euv = CTRL.y > 0.5, overlay = CTRL.z > 0.5;
    Cam k = starCam(makeCam(fetch(iChannel0, S_CAM, 0), res), CLOCK.y);
    vec3 rdw = camRay(k, P);
    // Work in the space where the star is the unit sphere.
    vec3 ro = k.ro / AX, rdu = rdw / AX; float L = length(rdu); vec3 rd = rdu / L;
    float fp = 1.0 / k.focal;                       // world size of a pixel per unit distance
    float b = dot(ro, rd), c = dot(ro, ro) - 1.0, h = b * b - c;
    float tS = h > 0.0 ? -b - sqrt(h) : -1.0;
    float edge = sqrt(max(dot(ro, ro) - b * b, 0.0)) - 1.0, pxw = -b * fp;
    float cover = smoothstep(0.75 * pxw, -0.75 * pxw, edge);
    vec3 col = vec3(0); float E = 0.0; FIL = 0.0;
    if (cover > 0.0) {
        vec3 sp = h > 0.0 ? ro + rd * tS : normalize(ro - rd * b);
        vec3 nE = normalize(sp / AX);
        float mu = max(dot(nE, -rdw), 0.0);
        float fps = (h > 0.0 ? tS : -b) * fp / sqrt(max(mu, 0.04));
        vec3 sc = surface(normalize(sp), mu, fps, euv);
        if (euv) E += sc.x * cover; else col = sc * cover;
    }
    vec2 at = atmosphere(ro, rd, tS, euv);
    vec4 ov = vec4(0); float lu = 0.0; vec2 cl = vec2(0);
    if (euv || overlay) fieldLines(ro, rd, tS, fp / L, P, euv, overlay, ov, lu, cl);
    if (euv) {
        // Filaments sit in the low corona: they absorb the disc and the corona behind them.
        E = (E + at.x + lu) * (1.0 - FIL * cover);
        col = palette304(log(1.0 + 2.2 * E) / log(1.0 + 2.2 * 2.5));
    } else {
        vec4 mol = planck(iChannel0, S.T * 0.6), ref = planck(iChannel0, S.T * 1.0574);
        col = col * exp(-at.y) + at.x * exp(mol.w - ref.w) * mol.rgb * 6.0;
    }
    if (overlay) col = mix(col, ov.rgb / max(ov.a, 1e-4), sat(ov.a) * 0.85);
    O = vec4(max(col, 0.0), 1.0);
}

// Image: glare, tone mapping and the interface.
// iChannel0 = Buffer D (mipmap)   iChannel1 = Buffer A (state, text)   iChannel2 = font texture
//
// Strings are composed in Buffer A; each text pixel here costs one texel fetch and one font
// sample. The font is fixed-width with a half-em advance.

float U;                                              // UI scale: virtual px -> screen px
const vec3 INK = vec3(0.94, 0.92, 0.87), MUTED = vec3(0.55, 0.54, 0.51), ACC = vec3(1.0, 0.70, 0.32);

float tlen(int L) { return fetch(iChannel1, L, 7).x; }
// Line L at baseline-left org (virtual px), size em: fill plus a soft dark halo.
void text(inout vec3 col, vec2 p, vec2 org, float em, int L, vec3 ink) {
    vec2 q = (p - org) / em;
    if (q.y < -0.3 || q.y > 0.74 || q.x < 0.0) return;
    int i = int(q.x / 0.5);
    if (float(i) >= tlen(L)) return;
    vec4 t = fetch(iChannel1, L * 5 + i / 12, 6);
    int j = i % 12;
    float v = j < 3 ? t.x : j < 6 ? t.y : j < 9 ? t.z : t.w;
    uint c = (uint(v) >> uint(8 * (j % 3))) & 255u;
    if (c == 32u) return;
    vec2 uv = vec2(0.25 + q.x - 0.5 * float(i), 0.8 - q.y);
    float d = (textureLod(iChannel2, (vec2(float(c % 16u), float(c / 16u)) + uv) / 16.0, 0.0).a - 0.5) * em * U;
    col = mix(col, vec3(0), 0.55 * smoothstep(3.0, 0.0, d));
    col = mix(col, ink, smoothstep(0.65, -0.65, d));
}
// Right-aligned variant.
void textR(inout vec3 col, vec2 p, vec2 right, float em, int L, vec3 ink) { text(col, p, right - vec2(0.5 * em * tlen(L), 0), em, L, ink); }
float seg(vec2 p, vec2 a, vec2 b, float w) {
    vec2 v = b - a; float h = clamp(dot(p - a, v) / max(dot(v, v), 1e-4), 0.0, 1.0);
    return smoothstep(w + 0.6 / U, w - 0.6 / U, length(p - a - v * h));
}
vec3 aces(vec3 x) { return clamp(x * (2.51 * x + 0.03) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0); }
vec3 srgb(vec3 c) { return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c)); }

void mainImage(out vec4 O, in vec2 P) {
    vec2 res = iResolution.xy, uv = P / res;
    vec4 ctrl0 = fetch(iChannel1, S_CTRL, 0);
    vec3 sc = textureLod(iChannel0, uv, 0.0).rgb;
    vec3 glare = 0.30 * textureLod(iChannel0, uv, 2.5).rgb + 0.35 * textureLod(iChannel0, uv, 4.5).rgb + 0.35 * textureLod(iChannel0, uv, 6.5).rgb;
    // Hue-preserving: tone-map luminance, keep chromaticity, roll very bright colour toward white.
    vec3 hdr = (ctrl0.y > 0.5 ? 0.45 : 0.30) * (sc + 0.09 * glare);
    float Y = dot(hdr, vec3(0.2126, 0.7152, 0.0722)), Yt = aces(vec3(Y)).x;
    vec3 tm = hdr * (Yt / max(Y, 1e-5));
    tm = mix(tm, vec3(Yt), sat((max(tm.r, max(tm.g, tm.b)) - 1.0) * 1.5));
    vec3 col = srgb(clamp(tm, 0.0, 1.0));
    col += (hash13(vec3(P, iTime)) - 0.5) / 255.0;

    vec4 ctrl = fetch(iChannel1, S_CTRL, 0), slide = fetch(iChannel1, S_SLIDE, 0), cam = fetch(iChannel1, S_CAM, 0);
    vec4 camT = fetch(iChannel1, S_CAMT, 0);
    int star = int(ctrl.x + 0.5);
    U = uiScale(res);
    vec2 p = uiPoint(P, res);
    if (cam.w > 0.5) {
        text(col, p, vec2(906, 14), 13.0, TL_SHOW, MUTED);
        O = vec4(col, 1); return;
    }
    col *= mix(0.45, 1.0, smoothstep(0.0, 80.0, p.y));

    // Bottom panel.
    if (p.y < 76.0 && p.y > -2.0 && p.x > 0.0 && p.x < 960.0) {
        if (p.y > 40.0) {
            for (int k = 0; k < NSTARS; k++) {
                if (abs(p.x - starX(k) - 0.5 * starW(k)) > 0.5 * starW(k) + 8.0) continue;
                text(col, p, vec2(starX(k), 51.0), 14.0, TL_STAR + k, k == star ? INK : MUTED);
                if (k == star) col = mix(col, ACC, seg(p, vec2(starX(k), 45.5), vec2(starX(k) + starW(k), 45.5), 0.6));
            }
            bool euv = ctrl.y > 0.5;
            text(col, p, vec2(556, 51), 13.0, TL_VIS, euv ? MUTED : INK);
            text(col, p, vec2(623, 51), 13.0, TL_EUV, euv ? INK : MUTED);
            col = mix(col, ACC, seg(p, euv ? vec2(623, 45.5) : vec2(556, 45.5), euv ? vec2(642, 45.5) : vec2(601, 45.5), 0.6));
            col = mix(col, vec3(0.3), seg(p, vec2(612, 49), vec2(612, 58), 0.5));
            text(col, p, vec2(676, 51), 13.0, TL_FIELD, ctrl.z > 0.5 ? INK : MUTED);
            if (ctrl.z > 0.5) col = mix(col, ACC, seg(p, vec2(676, 45.5), vec2(708, 45.5), 0.6));
            text(col, p, vec2(741, 51), 13.0, TL_PAUSE, ctrl.w > 0.5 ? ACC : MUTED);
            col = mix(col, MUTED, seg(p, vec2(810, 54), vec2(818, 54), 0.7));
            col = mix(col, MUTED, max(seg(p, vec2(871, 54), vec2(879, 54), 0.7), seg(p, vec2(875, 50), vec2(875, 58), 0.7)));
            text(col, p, vec2(845.0 - 3.25 * tlen(TL_ZOOM), 51.0), 13.0, TL_ZOOM, INK);
            text(col, p, vec2(902, 51), 13.0, TL_HIDE, MUTED);
        } else {
            // The four sliders. The tick marks the real star's value once you move away from it.
            vec4 pre = presetSliders(star);
            for (int k = 0; k < 4; k++) {
                vec2 sp = sliderSpan(k);
                if (p.x < sp.x - 10.0 || p.x > sp.y + 10.0) continue;
                float v = k == 0 ? slide.x : k == 1 ? slide.y : k == 2 ? slide.z : slide.w;
                float pv = k == 0 ? pre.x : k == 1 ? pre.y : k == 2 ? pre.z : pre.w;
                float kx = mix(sp.x, sp.y, v);
                col = mix(col, vec3(0.28), seg(p, vec2(sp.x, TRACK), vec2(sp.y, TRACK), 0.7));
                col = mix(col, vec3(0.78), seg(p, vec2(sp.x, TRACK), vec2(kx, TRACK), 0.9));
                if (camT.w > 0.5) col = mix(col, ACC * 0.8, seg(p, vec2(mix(sp.x, sp.y, pv), TRACK - 4.5), vec2(mix(sp.x, sp.y, pv), TRACK + 4.5), 0.5));
                col = mix(col, INK, smoothstep(4.6 + 0.6 / U, 4.6 - 0.6 / U, length(p - vec2(kx, TRACK))));
                text(col, p, vec2(sp.x, 25.0), 13.0, TL_SLAB + k, MUTED);
                textR(col, p, vec2(sp.y, 25.0), 13.0, TL_SVAL + k, INK);
            }
        }
    }
    O = vec4(clamp(col, 0.0, 1.0), 1);
}
